'use strict';
(() => {
  const D=window.WOLF_DEMO;
  const view=document.getElementById('view');
  const state={view:'overview',days:7,query:'',type:'all',status:'all',special:'all',page:0,stewardType:'all',origin:'all'};
  const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',memory:'<path d="M4 5c4-2 6-1 8 1v15c-2-2-4-3-8-1zM20 5c-4-2-6-1-8 1v15c2-2 4-3 8-1z"/>',usage:'<path d="M3 13h4l3-8 4 15 3-7h4"/>',steward:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',metrics:'<path d="M5 3h14v18H5zM8 8h8M8 12h8M8 16h4"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 8.8a2.7 2.7 0 0 1 5 1.4c0 2-2.5 2-2.5 4M12 17h.01"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7M12 7h.01"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',flow:'<path d="M5 3v12a4 4 0 0 0 4 4h10m-4-4 4 4-4 4M9 7h10m-4-4 4 4-4 4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>'};
  const icon=n=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(icons[n]||icons.info)+'</svg>';
  document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num=n=>new Intl.NumberFormat('ru-RU').format(n);
  const date=s=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',timeZone:'Europe/Moscow'}).format(new Date(s));
  const kb=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(n/1024)+' КБ';
  const period=items=>items.filter(x=>Date.parse(x.ts)>=Date.parse(D.asOf)-(state.days-1)*86400000&&Date.parse(x.ts)<=Date.parse(D.asOf));
  const byId=id=>D.memories.find(m=>m.id===id);
  const active=()=>D.memories.filter(m=>m.status==='active');
  const stageCounts=(items,id)=>items.filter(e=>e.id===id).length;
  const touched=()=>new Set([...period(D.reads),...period(D.injections)].map(e=>e.id));
  const closed=()=>active().filter(m=>m.memory_class==='working'&&m.threadClosed);
  const oldDeliveries=()=>period(D.injections).filter(e=>{const m=byId(e.id);return m?.replacedAt&&e.ts>m.replacedAt;});
  const interventions=()=>period(D.interventions);
  const origin=id=>{const m=D.metrics.find(x=>x.id===id);const o=D.origins[m.origin];return '<span class="origin '+o.className+'">'+o.label+'</span>';};
  const info=id=>'<button class="metric-info" data-metric="'+id+'" aria-label="Определение показателя: '+esc(D.metrics.find(m=>m.id===id)?.name)+'">'+icon('info')+'</button>';
  const statusLabel=s=>({active:'Активна',archived:'Архив',superseded:'Заменена',open:'Открыта',resolved:'Разрешена',rejected:'Отклонена'}[s]||s);
  const status=s=>'<span class="status '+(s==='open'?'pending':s)+'">'+statusLabel(s)+'</span>';
  const typeName=k=>D.typeNames[k]||k;
  const kpi=(label,value,bottom,metric)=>'<div class="kpi"><div class="kpi-top"><span>'+label+'</span>'+info(metric)+'</div><div class="kpi-value">'+value+'</div><div class="kpi-bottom">'+bottom+'</div></div>';
  const notice=(text,cls='')=>'<div class="notice '+cls+'">'+icon('info')+'<div>'+text+'</div></div>';
  function bucketEvents(){const buckets=[];const span=state.days===7?1:5;for(let n=30-state.days;n<30;n+=span){const start=D.day(n),end=D.day(Math.min(n+span-1,29));const e=period(D.audit).filter(x=>x.ts>=start&&x.ts<=end);const count=kind=>new Set(e.filter(x=>kind.includes(x.kind)).map(x=>x.id+':'+x.ts.slice(0,10))).size;buckets.push({label:state.days===7?date(start).replace('.',''):date(start),created:count(['created']),changed:count(['updated']),archived:count(['archived','superseded'])});}return buckets;}
  function flowChart(){const b=bucketEvents(),max=Math.max(1,...b.map(x=>x.created+x.changed+x.archived));return '<div class="bar-chart" role="img" aria-label="Движение памяти по дням: создание, изменение, архивирование или замена">'+b.map(x=>{const total=x.created+x.changed+x.archived;return '<div class="bar-col"><span class="bar-count">'+total+'</span><div class="bar-stack" style="height:'+Math.max(2,total/max*135)+'px" aria-label="'+esc(x.label+': создано '+x.created+', изменено '+x.changed+', архив или замена '+x.archived)+'"><div class="bar-segment" style="height:'+(total?x.created/total*100:0)+'%;background:#4d7d59"></div><div class="bar-segment" style="height:'+(total?x.changed/total*100:0)+'%;background:#a4bd8f"></div><div class="bar-segment" style="height:'+(total?x.archived/total*100:0)+'%;background:#d9dfce"></div></div></div>';}).join('')+'</div><div class="chart-labels">'+b.map(x=>'<span>'+x.label+'</span>').join('')+'</div><div class="chart-caption">'+(state.days===30?'Столбец — 5 дней. ':'')+'Внутри вида действия запись считается один раз в день. Это события, а не остаток памяти.</div>';}
  function distribution(mode='type'){const groups=new Map();for(const m of D.memories){const key=mode==='type'?m.type:m.memory_class;const g=groups.get(key)||{count:0,bytes:0};g.count++;g.bytes+=m.bytes;groups.set(key,g);}const total=D.memories.reduce((s,m)=>s+m.bytes,0);return '<div class="distribution">'+[...groups].sort((a,b)=>b[1].bytes-a[1].bytes).map(([key,g])=>'<button class="dist-row" data-composition="'+key+'" data-mode="'+mode+'"><div class="dist-meta"><span class="dist-title">'+esc(mode==='type'?typeName(key):key==='canonical'?'Каноническая':'Рабочая')+'</span><span class="dist-number">'+g.count+' · '+kb(g.bytes)+'</span></div><div class="track"><div class="fill" style="width:'+(g.bytes/total*100)+'%"></div></div></button>').join('')+'</div>';}
  function basicKpis(){const a=active(),t=touched(),n=a.filter(m=>t.has(m.id)).length;return '<div class="kpi-grid">'+kpi('Записей в памяти',num(D.memories.length),'<span class="accent">'+a.length+' активных</span> · '+D.memories.filter(m=>m.status==='archived').length+' в архиве','stock')+kpi('С обращениями',n+' <span class="unit">/ '+a.length+'</span>','Активные записи за '+state.days+' дней','touched')+kpi('Вмешательств Стюарда',num(interventions().length),'Отдельные завершённые операции','steward')+kpi('Объём памяти',kb(D.memories.reduce((s,m)=>s+m.bytes,0)).replace(' КБ',' <span class="unit">КБ</span>'),'Все статусы, включая архив','bytes')+'</div>';}
  function insights(){const c=closed().length,o=oldDeliveries().length,a=interventions().filter(x=>x.kind==='aggregation'),sources=new Set(a.flatMap(x=>x.sourceIds)).size;return '<div class="section-head"><h2>Что можно заметить</h2><span>Выводы по условным данным</span></div><div class="insight-grid"><article class="insight"><span class="insight-number">01 / СОСТАВ ПАМЯТИ</span><h3>'+c+' рабочих записей связаны с закрытыми задачами</h3><p>Это очередь на пересмотр. Сначала нужно проверить, сохранены ли результаты и основания приёмки.</p><div class="benefit">Польза: адресно обслуживать рабочую память, не перечитывая весь архив.</div><button data-action="closed">Посмотреть записи →</button></article><article class="insight"><span class="insight-number">02 / АКТУАЛЬНОСТЬ</span><h3>'+o+' доставки заменённых записей</h3><p>Сверить момент замены и контекст сессии: прежняя версия может быть намеренно закреплена для уже начатой работы.</p><div class="benefit">Польза: отличать допустимое продолжение от проблемы доставки.</div><button data-action="old">Проверить доставки →</button></article><article class="insight"><span class="insight-number">03 / РАБОТА СТЮАРДА</span><h3>'+a.length+' объединения, '+sources+' исходных записей</h3><p>Видны основания, итоговые агрегаты и судьба исходников. Качество улучшения автоматически не оценивается.</p><div class="benefit">Польза: проверять действия Стюарда и сохранять происхождение знаний.</div><button data-action="aggregation">Открыть вмешательства →</button></article></div>';}
  function storagePanel(){const mem=D.storage[0].bytes,logs=D.storage.slice(3).reduce((s,x)=>s+x.bytes,0),max=Math.max(...D.storage.map(x=>x.bytes));return '<section class="panel section-space"><div class="panel-head"><div><h2>Цена наблюдения в хранении</h2><p>Условный снимок на дату демо; физические размеры, включая архивы</p></div>'+info('storage')+'</div><div class="half-column"><div class="distribution">'+D.storage.map(x=>'<div><div class="dist-meta"><span>'+x.name+'</span><span class="dist-number">'+kb(x.bytes)+'</span></div><div class="track"><div class="fill" style="width:'+(x.bytes/max*100)+'%"></div></div><p class="chart-caption">'+x.purpose+'</p></div>').join('')+'</div><div><div class="kpi-value">'+new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(logs/mem)+' <span class="unit">× объёма памяти</span></div><p class="proof-caption">В этом примере текущие и архивные журналы наблюдения вместе занимают '+kb(logs)+'. По одному снимку нельзя определить скорость их роста.</p>'+notice('<strong>Повод проверить политику хранения.</strong> Выяснить, какие сырые журналы нужны для диагностики, а какие можно заменять агрегатами после ограниченного окна.','neutral')+'<p class="proof-caption">История изменений и связи выделены отдельно: это источники восстановления и происхождения. Архивация объектов сама по себе не освобождает место.</p><button class="drawer-link" data-metric="storage">Источник, расчёт и ограничения →</button></div></div></section>';}
  function overview(){return basicKpis()+'<div class="two-column"><section class="panel"><div class="panel-head"><div><h2>Движение памяти</h2><p>Что создают, уточняют и выводят из активной работы</p></div>'+info('flow')+'</div><div class="legend"><span><i class="swatch" style="background:#4d7d59"></i>Создано</span><span><i class="swatch" style="background:#a4bd8f"></i>Изменено</span><span><i class="swatch" style="background:#d9dfce"></i>Архив / замена</span></div>'+flowChart()+'</section><section class="panel"><div class="panel-head"><div><h2>Где находится память</h2><p>Количество и объём по типам на дату снимка</p></div>'+info('bytes')+'</div>'+distribution()+'</section></div>'+insights()+'<div class="half-column"><section class="panel"><div class="panel-head"><div><h2>Последние действия Стюарда</h2><p>Причина → действие → затронутая память</p></div><button class="text-button" data-action="steward">Все действия →</button></div>'+recentSteward()+'</section><section class="panel"><div class="panel-head"><div><h2>Границы наблюдения</h2><p>Чтобы неизвестное не выглядело нулём</p></div>'+info('applied')+'</div>'+notice('<strong>Применение воспоминаний пока не наблюдается.</strong> Доступны чтение и доставка; это разные факты.','neutral')+'<div class="mini-grid"><div class="mini-kpi"><strong>'+num(period(D.skills).length)+'</strong><span>вызовов skill; соблюдение не проверяется</span></div><div class="mini-kpi"><strong>Нет данных</strong><span>атрибутированные расходы Стюарда</span></div></div><p class="proof-caption">Прототип не запускает повторные задачи ради измерения. Источники и предложенные расчёты открыты в каталоге метрик.</p></section></div>'+storagePanel();}
  function memoryList(){let list=D.memories.filter(m=>(state.type==='all'||m.type===state.type)&&(state.status==='all'||m.status===state.status));const t=touched();if(state.special==='unread')list=list.filter(m=>m.status==='active'&&!t.has(m.id));if(state.special==='closed')list=list.filter(m=>m.status==='active'&&m.memory_class==='working'&&m.threadClosed);if(state.special==='canonical'||state.special==='working')list=list.filter(m=>m.memory_class===state.special);const q=state.query.toLocaleLowerCase('ru');if(q)list=list.filter(m=>(m.title+' '+m.id).toLocaleLowerCase('ru').includes(q));return list;}
  function memoryTable(){const rows=memoryList(),pages=Math.max(1,Math.ceil(rows.length/10));state.page=Math.min(state.page,pages-1);const shown=rows.slice(state.page*10,state.page*10+10);return '<section class="panel table-panel"><div class="table-heading"><div><h2>Записи памяти</h2><p>Найдено '+rows.length+' · чтения и доставки за '+state.days+' дней</p></div>'+info('touched')+'</div><div class="table-scroll"><table><thead><tr><th>Запись</th><th>Тип</th><th>Статус</th><th class="numeric">Чтения</th><th class="numeric">Доставки</th><th class="numeric">Объём</th></tr></thead><tbody>'+shown.map(m=>'<tr class="clickable" data-memory="'+m.id+'"><td><button class="text-button record-title" data-memory="'+m.id+'"><span class="name">'+esc(m.title)+'</span></button><span class="sub">'+m.id+' · '+(m.memory_class==='canonical'?'каноническая':'рабочая')+'</span></td><td>'+typeName(m.type)+'</td><td>'+status(m.status)+'</td><td class="numeric">'+stageCounts(period(D.reads),m.id)+'</td><td class="numeric">'+stageCounts(period(D.injections),m.id)+'</td><td class="numeric">'+kb(m.bytes)+'</td></tr>').join('')+'</tbody></table>'+(rows.length?'':'<div class="empty">Подходящих записей нет. Измени фильтр или запрос.</div>')+'</div><div class="pagination"><span>'+(rows.length?(state.page*10+1)+'–'+Math.min(rows.length,state.page*10+10)+' из '+rows.length:'Нет записей')+'</span><div><button class="small-button" data-page="-1" '+(state.page===0?'disabled':'')+' aria-label="Предыдущая страница">←</button><button class="small-button" data-page="1" '+(state.page>=pages-1?'disabled':'')+' aria-label="Следующая страница">→</button></div></div></section>';}
  function memory(){const t=touched(),unread=active().filter(m=>!t.has(m.id)).length;return '<div class="half-column"><section class="panel"><div class="panel-head"><div><h2>Распределение по назначению</h2><p>Текущее состояние; история категорий требует отдельного источника</p></div>'+info('classes')+'</div>'+distribution('class')+'</section><section class="panel"><div class="panel-head"><div><h2>Память, требующая внимания</h2><p>Кандидаты на просмотр, без автоматического удаления</p></div>'+info('closed')+'</div><div class="mini-grid"><div class="mini-kpi"><strong>'+closed().length+'</strong><span>рабочих записей закрытых задач</span></div><div class="mini-kpi"><strong>'+unread+'</strong><span>активных записей без обращений за период</span></div></div></section></div><div class="filters"><label class="search-wrap" aria-label="Поиск записей">'+icon('search')+'<input id="memory-search" type="search" placeholder="Найти по названию или ID" value="'+esc(state.query)+'"></label><select id="memory-type" aria-label="Тип памяти"><option value="all">Все типы</option>'+Object.entries(D.typeNames).map(([k,v])=>'<option value="'+k+'" '+(state.type===k?'selected':'')+'>'+v+'</option>').join('')+'</select><select id="memory-status" aria-label="Статус записи"><option value="all">Все статусы</option>'+['active','archived','superseded'].map(k=>'<option value="'+k+'" '+(state.status===k?'selected':'')+'>'+statusLabel(k)+'</option>').join('')+'</select></div><div class="chip-row">'+[['all','Все записи'],['unread','Без обращений'],['closed','Закрытые задачи'],['working','Рабочая'],['canonical','Каноническая']].map(([k,v])=>'<button class="chip '+(state.special===k?'active':'')+'" data-special="'+k+'" aria-pressed="'+(state.special===k)+'">'+v+'</button>').join('')+'</div>'+(state.special==='closed'?notice('Эта выборка связывает рабочие записи с завершёнными thread. Перед архивацией нужно проверить evidence и незакрытые зависимости.'):state.special==='unread'?notice('Здесь нет чтений или доставок в выбранном окне. Редкое правило может оставаться нужным.','neutral'):'')+'<div id="memory-table-wrapper">'+memoryTable()+'</div>';}
  function topUsage(){const rs=period(D.reads),ins=period(D.injections);return D.memories.map(m=>({...m,r:stageCounts(rs,m.id),i:stageCounts(ins,m.id)})).filter(m=>m.r||m.i).sort((a,b)=>b.r+b.i-a.r-a.i).slice(0,8);}
  function usage(){const rs=period(D.reads),ins=period(D.injections),rt=period(D.routes),fallback=rt.filter(r=>r.fallback).length;const skills=new Map();for(const s of period(D.skills))skills.set(s.name,(skills.get(s.name)||0)+1);return '<div class="kpi-grid">'+kpi('Извлечений памяти',num(rs.length),new Set(rs.map(x=>x.id)).size+' уникальных записей','reads')+kpi('Доставок в контекст',num(ins.length),new Set(ins.map(x=>x.id)).size+' уникальных записей','reads')+kpi('Вызовов скиллов',num(period(D.skills).length),'Только наблюдаемые вызовы skill','skills')+kpi('Fallback маршрутизатора',fallback+' <span class="unit">/ '+rt.length+'</span>','Число строк журнала, не сессий','routing')+'</div>'+notice('<strong>Чтение, доставка и применение — отдельные события.</strong> Доставка может происходить без отдельного get. Эти числа не образуют воронку успешности.','neutral')+'<div class="two-column"><section class="panel table-panel"><div class="table-heading"><div><h2>К каким записям обращаются</h2><p>Наиболее частые обращения за период</p></div>'+info('touched')+'</div><div class="table-scroll"><table><thead><tr><th>Запись</th><th class="numeric">Чтения</th><th class="numeric">Доставки</th></tr></thead><tbody>'+topUsage().map(m=>'<tr data-memory="'+m.id+'" class="clickable"><td><button class="text-button" data-memory="'+m.id+'"><span class="name">'+esc(m.title)+'</span></button><span class="sub">'+typeName(m.type)+' · '+statusLabel(m.status)+'</span></td><td class="numeric">'+m.r+'</td><td class="numeric">'+m.i+'</td></tr>').join('')+'</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Что известно о применении</h2><p>Уровни наблюдения с разной полнотой</p></div>'+info('applied')+'</div><div class="stage-list"><div class="stage-box"><div class="stage-label">Извлечено</div><div class="stage-num">'+new Set(rs.map(x=>x.id)).size+'</div><div class="stage-note">уникальных ID из retrieved</div></div><div class="stage-box"><div class="stage-label">Доставлено</div><div class="stage-num">'+new Set(ins.map(x=>x.id)).size+'</div><div class="stage-note">уникальных ID из injected</div></div><div class="stage-box missing"><div class="stage-label">Процитировано</div><div class="stage-num">Нет источника</div><div class="stage-note">штатный писатель не найден</div></div><div class="stage-box missing"><div class="stage-label">Применено</div><div class="stage-num">Неизвестно</div><div class="stage-note">get/search не доказывает применение</div></div></div></section></div><div class="half-column"><section class="panel"><div class="panel-head"><div><h2>Загружаемые скиллы</h2><p>Частота обращения, без оценки эффективности</p></div>'+info('skills')+'</div><div class="distribution">'+[...skills].sort((a,b)=>b[1]-a[1]).map(([s,n])=>'<div><div class="dist-meta"><span>'+s+'</span><span class="dist-number">'+n+'</span></div><div class="track"><div class="fill" style="width:'+n/Math.max(...skills.values())*100+'%"></div></div></div>').join('')+'</div></section><section class="panel"><div class="panel-head"><div><h2>Доставка после замены</h2><p>Адресные случаи для проверки контекста сессии</p></div>'+info('old')+'</div>'+oldDeliveries().map(e=>'<button class="drawer-link" data-memory="'+e.id+'">'+esc(byId(e.id).title)+'<small style="display:block;color:#8b9982;margin-top:5px">Доставлено '+date(e.ts)+' · заменено '+date(byId(e.id).replacedAt)+'</small></button>').join('')+(oldDeliveries().length?'':'<p class="proof-caption">В выбранном периоде таких доставок нет.</p>')+'<p class="proof-caption">Закреплённая версия в уже начатой сессии может быть допустима. Эта находка не объявляется ошибкой автоматически.</p></section></div><section class="panel"><div class="panel-head"><div><h2>Прохождение процессов</h2><p>Отдельный вопрос, который частота вызовов skill не решает</p></div>'+info('processes')+'</div>'+notice('<strong>Пока нет достаточного источника.</strong> Нужна связь этапов TASK/thread с результатом и evidence, возвратами и пропусками. Используем факты обычной работы, без повторного выполнения задач.','neutral')+'</section>';}
  const kindLabels={aggregation:'Агрегация',face:'Лицо',skill:'Скилл',rule:'Правило',refresh:'Актуализация'};
  function recentSteward(){return '<div class="action-list">'+interventions().slice().reverse().slice(0,3).map(i=>'<div class="action-row"><div class="action-symbol">'+icon(i.kind==='aggregation'?'flow':'steward')+'</div><div class="action-main"><button class="text-button" data-intervention="'+i.id+'"><span>'+esc(i.title)+'</span></button><small>'+date(i.ts)+' · '+kindLabels[i.kind]+'</small></div></div>').join('')+'</div>';}
  function steward(){const items=interventions(),generic=period(D.audit).filter(e=>['updated','transition','superseded','archived','tool_used'].includes(e.kind)).length;const complaints=period(D.complaints),open=D.complaints.filter(c=>c.status==='open').length,agg=items.filter(x=>x.kind==='aggregation');let list=items.filter(i=>state.stewardType==='all'||i.kind===state.stewardType).reverse();return '<div class="kpi-grid">'+kpi('Вмешательств',num(items.length),'Одна операция считается один раз','steward')+kpi('Исходников объединено',new Set(agg.flatMap(i=>i.sourceIds)).size,'В '+agg.length+' операциях агрегации','aggregation')+kpi('Открытых жалоб',open,'Текущий остаток, не поток за период','complaints')+kpi('Расходы Стюарда','<span style="font-size:21px">Неизвестно</span>','Полная атрибуция не подключена','stewardCost')+'</div><div class="half-column"><section class="panel"><div class="panel-head"><div><h2>Действия Стюарда отдельно от общего журнала</h2><p>Два разных счётчика — для разных вопросов</p></div>'+info('steward')+'</div><div class="comparison"><div><span class="label">Общие операции над памятью</span><div class="big bad-number">'+generic+'</div></div><div><span class="label">Вмешательства Стюарда</span><div class="big correct-number">'+items.length+'</div></div></div><p class="comparison-note">Обновления L1, tool use и дочерние шаги операции не становятся отдельными вмешательствами Стюарда. В прототипе показан предлагаемый исправленный расчёт.</p></section><section class="panel"><div class="panel-head"><div><h2>Жалобы и их состояние</h2><p>Поступления за период и текущие статусы объектов</p></div>'+info('complaints')+'</div><div class="action-list">'+[['Подано за период',complaints.length],['Разрешено из поступивших',complaints.filter(c=>c.status==='resolved').length],['Отклонено из поступивших',complaints.filter(c=>c.status==='rejected').length],['Всего открыто на дату снимка',open]].map(([label,n])=>'<div class="action-row"><div class="action-main"><p>'+label+'</p></div><span class="action-count">'+n+'</span></div>').join('')+'</div></section></div><div class="section-head"><h2>История вмешательств</h2><span>Факт действия и его основание</span></div><div class="chip-row">'+[['all','Все'],...Object.entries(kindLabels)].map(([k,v])=>'<button class="chip '+(state.stewardType===k?'active':'')+'" data-steward-type="'+k+'" aria-pressed="'+(state.stewardType===k)+'">'+v+'</button>').join('')+'</div><section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Действие</th><th>Основание</th><th>Дата</th><th>Состояние</th></tr></thead><tbody>'+list.map(i=>'<tr data-intervention="'+i.id+'" class="clickable"><td><button class="text-button" data-intervention="'+i.id+'"><span class="name">'+esc(i.title)+'</span></button><span class="sub">'+kindLabels[i.kind]+' · '+i.steps+' шагов в одной операции</span></td><td><span style="display:block;max-width:330px;font-size:11px;line-height:1.6;color:#7a8870">'+esc(i.reason)+'</span></td><td style="white-space:nowrap">'+date(i.ts)+'</td><td><span class="status">Завершено</span></td></tr>').join('')+'</tbody></table>'+(list.length?'':'<div class="empty">За этот период вмешательств выбранного вида нет.</div>')+'</div></section>'+notice('<strong>Завершённое вмешательство — подтверждённое действие.</strong> Отсутствие новых жалоб не доказывает улучшение. Повторные задачи ради оценки в этом контуре не запускаются.','neutral');}
  function metrics(){const ms=D.metrics.filter(m=>state.origin==='all'||m.origin===state.origin);return notice('<strong>Что означают значения в прототипе.</strong> Все числа условные. Метки ниже показывают готовность показателя в Wolf 2.25.1: существующий, требующий исправления, новый расчёт или отсутствующий источник.','neutral')+'<div class="chip-row"><button class="chip '+(state.origin==='all'?'active':'')+'" data-origin="all" aria-pressed="'+(state.origin==='all')+'">Все показатели <span class="n">'+D.metrics.length+'</span></button>'+Object.entries(D.origins).map(([k,v])=>'<button class="chip '+(state.origin===k?'active':'')+'" data-origin="'+k+'" aria-pressed="'+(state.origin===k)+'">'+v.label+'<span class="n">'+D.metrics.filter(m=>m.origin===k).length+'</span></button>').join('')+'</div><section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Показатель</th><th>На какой вопрос отвечает</th><th>Готовность</th></tr></thead><tbody>'+ms.map(m=>'<tr class="clickable" data-metric="'+m.id+'"><td><button class="text-button" data-metric="'+m.id+'"><span class="name">'+m.name+'</span></button></td><td style="line-height:1.6;color:#7e8a75">'+m.question+'</td><td>'+origin(m.id)+'</td></tr>').join('')+'</tbody></table></div></section><div class="half-column section-space"><section class="panel"><div class="panel-head"><h2>Какие выводы допустимы</h2></div><p class="proof-caption">«Стюард завершил операции с известным авторством». «К этим записям были обращения». «В архиве сохранены исходники агрегата». Это наблюдаемые факты.</p><p class="proof-caption">«Память сэкономила 30%». «Этот скилл повысил качество». Таких выводов эти данные не подтверждают.</p></section><section class="panel"><div class="panel-head"><h2>Что добавлено к существующим метрикам</h2></div><p class="proof-caption">Размеры по назначению, рабочая память закрытых задач, адресная проверка доставок после замены, происхождение агрегаций и корректное авторство вмешательств.</p><p class="proof-caption">Подтверждённое применение, расходы Стюарда и история категорий оставлены неизвестными до появления достаточного источника.</p></section></div>';}
  const titles={overview:['ЖИЗНЬ ПАМЯТИ','Что происходит в системе','Память, обращения и действия Стюарда — в одной картине.'],memory:['СОСТАВ И АКТУАЛИЗАЦИЯ','Что хранится в памяти','Разбирай активные записи, версии и рабочий контекст по назначению.'],usage:['ОБРАЩЕНИЯ И ДОСТАВКА','Как используется память','Видно, что прочитано и доставлено. Неизвестное применение остаётся неизвестным.'],steward:['ОБСЛУЖИВАНИЕ ЗНАНИЙ','Что делает Стюард','Основания, вмешательства и затронутые записи — без вымышленной оценки улучшений.'],metrics:['ОПРЕДЕЛЕНИЯ И ГРАНИЦЫ','Что именно мы измеряем','Для каждого показателя — вопрос, расчёт, источник и ограничение вывода.']};
  function render(){const t=titles[state.view];document.getElementById('page-eyebrow').textContent=t[0];document.getElementById('page-title').textContent=t[1];document.getElementById('page-subtitle').textContent=t[2];document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===state.view);if(a.dataset.nav===state.view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});view.innerHTML=({overview,memory,usage,steward,metrics}[state.view])();}
  function navigate(v){closeDrawer();if(location.hash==='#'+v){state.view=v;render();}else location.hash=v;}
  function route(){const v=location.hash.slice(1);state.view=titles[v]?v:'overview';render();}
  let returnFocus=null;
  function openDrawer(kicker,html){if(document.getElementById('drawer').hidden)returnFocus=document.activeElement;document.getElementById('drawer-kicker').textContent=kicker;document.getElementById('drawer-content').innerHTML=html;document.getElementById('overlay').hidden=false;document.getElementById('drawer').hidden=false;document.getElementById('drawer').scrollTop=0;document.body.style.overflow='hidden';document.getElementById('close-drawer').focus();}
  function closeDrawer(){const was=!document.getElementById('drawer').hidden;document.getElementById('drawer').hidden=true;document.getElementById('overlay').hidden=true;document.body.style.overflow='';if(was&&returnFocus?.isConnected)returnFocus.focus();}
  function metricDrawer(id){const m=D.metrics.find(m=>m.id===id);if(!m)return;openDrawer('ПАСПОРТ ПОКАЗАТЕЛЯ','<h2 id="drawer-title">'+m.name+'</h2>'+origin(m.id)+'<p class="lead">'+m.question+'</p><h3>Как считается</h3><p class="lead">'+m.formula+'</p><h3>Что уже есть в Wolf</h3><p class="lead">'+m.current+'</p><h3>Источник</h3><p class="lead">'+m.source+'</p>'+notice(m.limit,'amber')+'<p class="footnote">Паспорт описывает предлагаемую семантику показателя. Условные данные прототипа не означают, что новый расчёт уже реализован в Wolf.</p><a class="drawer-link" href="https://github.com/chekh/mister-wolf/blob/v2.25.1/src/app/use-cases/build-analytics.ts" target="_blank" rel="noopener noreferrer">Посмотреть текущую аналитику в репозитории ↗</a>');}
  function memoryDrawer(id){const m=byId(id);if(!m)return;const r=period(D.reads).filter(e=>e.id===id),ins=period(D.injections).filter(e=>e.id===id);const events=[...period(D.audit).filter(e=>e.id===id).map(e=>({...e,label:({created:'Создана запись',updated:'Обновлена запись',archived:'Переведена в архив',superseded:'Заменена новой записью',transition:'Шаг изменения статуса',tool_used:'Учтено использование инструмента'})[e.kind]})),...r.map(e=>({...e,label:'Извлечена из памяти',actor:e.agent})),...ins.map(e=>({...e,label:'Доставлена в контекст',actor:e.agent}))].sort((a,b)=>b.ts.localeCompare(a.ts)).slice(0,9);openDrawer('ЗАПИСЬ ПАМЯТИ','<h2 id="drawer-title">'+esc(m.title)+'</h2>'+status(m.status)+'<p class="footnote"><code>'+m.id+'</code></p><dl class="detail-list">'+[['Тип',typeName(m.type)],['Назначение',m.memory_class==='canonical'?'Каноническая память':'Рабочая память'],['Создана',date(m.createdAt)],['Обновлена',date(m.updatedAt)],['Объём',kb(m.bytes)],['Чтения / доставки',r.length+' / '+ins.length+' за '+state.days+' дней'],['Связанный thread',m.threadClosed?'Завершён':'Нет отметки завершённого thread'],['Применение','Неизвестно: источник не подключён']].map(([k,v])=>'<div class="detail-row"><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl>'+(m.status==='superseded'?notice('Запись заменена '+date(m.replacedAt)+'. Доставку после этого момента нужно сверять с закреплённой версией и контекстом сессии.','amber'):'')+(m.threadClosed&&m.status==='active'?notice('Кандидат на пересмотр после завершения задачи. Сначала проверить нужность evidence и будущих зависимостей.','neutral'):'')+'<h3>Последние наблюдения за период</h3><div class="timeline">'+events.map(e=>'<div class="timeline-entry"><small>'+date(e.ts)+' · '+esc(e.actor)+'</small>'+esc(e.label)+'</div>').join('')+(events.length?'':'<p class="proof-caption">Наблюдаемых событий в выбранном периоде нет.</p>')+'</div><p class="footnote">Все сведения в этой карточке — демонстрационные. Чтение и изменение записи показаны раздельно.</p>');}
  function interventionDrawer(id){const i=D.interventions.find(i=>i.id===id);if(!i)return;openDrawer('ВМЕШАТЕЛЬСТВО СТЮАРДА','<h2 id="drawer-title">'+i.title+'</h2><span class="status">Операция завершена</span><dl class="detail-list">'+[['Дата',date(i.ts)],['Автор',i.actor],['Операция',i.id],['Вид',kindLabels[i.kind]],['Дочерних шагов',i.steps+' — одно вмешательство']].map(([k,v])=>'<div class="detail-row"><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl><h3>Основание</h3><p class="lead">'+i.reason+'</p><h3>Что изменено</h3><dl class="detail-list"><div class="detail-row"><dt>Было</dt><dd>'+esc(i.before)+'</dd></div><div class="detail-row"><dt>Стало</dt><dd>'+esc(i.after)+'</dd></div></dl><h3>Затронутая память</h3><button class="drawer-link" data-memory="'+i.targetId+'">'+esc(i.targetName)+' →</button>'+i.sourceIds.map(id=>'<button class="drawer-link" data-memory="'+id+'">Исходник: '+esc(byId(id).title)+' · '+statusLabel(byId(id).status)+'</button>').join('')+'<h3>Основание фиксации</h3><p class="lead">'+i.evidence+'</p>'+notice('Зафиксирован факт вмешательства и его результат в памяти. Улучшение качества или экономия автоматически не утверждаются.','neutral'));}
  function help(){openDrawer('РАБОТА С ДАШБОРДОМ','<h2 id="drawer-title">От наблюдения к действию</h2><p class="lead">Дашборд помогает обслуживать память и понимать работу Стюарда по фактам обычной работы.</p>'+[['Начни с обзора','Выбери 7 или 30 дней. Записи и объём — состояние на дату снимка; обращения и изменения — события выбранного периода.'],['Открой конкретную находку','Карточки «Что можно заметить» ведут к нужным записям или вмешательствам. Не требуется исследовать все логи.'],['Посмотри основание','Нажми на запись или действие Стюарда: увидишь автора, время, связи и доступную историю. Чтение отделено от изменения.'],['Проверь смысл показателя','Значок информации открывает формулу, источник и готовность метрики. «Нужен источник» не означает нулевое значение.'],['Прими адресное решение','Пересмотреть рабочие записи, проверить доставку старой версии, проследить агрегацию или уточнить сбор. Архивация и мутации из прототипа не выполняются.']].map(([a,b],j)=>'<div class="guide-step"><span class="num">0'+(j+1)+'</span><div><strong>'+a+'</strong><p>'+b+'</p></div></div>').join('')+'<h3>В чём практическая польза</h3><ul><li>Меньше ручного просмотра журналов: есть адресные записи и операции.</li><li>Понятно, откуда растёт память и что можно пересмотреть.</li><li>Действия Стюарда видны отдельно от системных обновлений.</li><li>Ошибочные названия метрик не создают вымышленную картину применения.</li></ul><p class="footnote">Все данные условные. Бюджет экономии, качество улучшений и польза скиллов в процентах здесь не моделируются.</p>');}
  view.addEventListener('click',e=>{
    const el=e.target.closest('[data-metric],[data-memory],[data-intervention],[data-action],[data-composition],[data-special],[data-page],[data-steward-type],[data-origin]');if(!el)return;
    if(el.dataset.metric){metricDrawer(el.dataset.metric);return;}
    if(el.dataset.memory){memoryDrawer(el.dataset.memory);return;}
    if(el.dataset.intervention){interventionDrawer(el.dataset.intervention);return;}
    if(el.dataset.action){if(el.dataset.action==='closed'){Object.assign(state,{query:'',type:'all',status:'all',special:'closed',page:0});navigate('memory');}else if(el.dataset.action==='old')navigate('usage');else{state.stewardType=el.dataset.action==='aggregation'?'aggregation':'all';navigate('steward');}return;}
    if(el.dataset.composition){Object.assign(state,{query:'',status:'all',page:0,type:el.dataset.mode==='type'?el.dataset.composition:'all',special:el.dataset.mode==='class'?el.dataset.composition:'all'});navigate('memory');return;}
    if(el.dataset.special){state.special=el.dataset.special;state.page=0;render();return;}
    if(el.dataset.page){state.page+=Number(el.dataset.page);document.getElementById('memory-table-wrapper').innerHTML=memoryTable();return;}
    if(el.dataset.stewardType){state.stewardType=el.dataset.stewardType;render();return;}
    if(el.dataset.origin){state.origin=el.dataset.origin;render();}
  });
  view.addEventListener('input',e=>{if(e.target.id==='memory-search'){state.query=e.target.value;state.page=0;document.getElementById('memory-table-wrapper').innerHTML=memoryTable();}});
  view.addEventListener('change',e=>{if(e.target.id==='memory-type'||e.target.id==='memory-status'){state[e.target.id==='memory-type'?'type':'status']=e.target.value;state.page=0;render();}});
  document.getElementById('drawer').addEventListener('click',e=>{const m=e.target.closest('[data-memory]');if(m)memoryDrawer(m.dataset.memory);});
  document.getElementById('period').addEventListener('change',e=>{state.days=Number(e.target.value);state.page=0;render();});
  document.getElementById('close-drawer').addEventListener('click',closeDrawer);document.getElementById('overlay').addEventListener('click',closeDrawer);document.getElementById('help-button').addEventListener('click',help);
  document.addEventListener('keydown',e=>{if(document.getElementById('drawer').hidden)return;if(e.key==='Escape'){e.preventDefault();closeDrawer();}if(e.key==='Tab'){const f=[...document.getElementById('drawer').querySelectorAll('button,a[href],select,input')].filter(x=>!x.disabled);const a=f[0],z=f[f.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus();}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus();}}});
  document.getElementById('export-button').addEventListener('click',()=>{const data={mode:'demonstration_only',asOf:D.asOf,periodDays:state.days,summary:{memoryObjects:D.memories.length,active:active().length,activeWithAccess:active().filter(m=>touched().has(m.id)).length,reads:period(D.reads).length,injections:period(D.injections).length,stewardInterventions:interventions().length,memoryBytes:D.memories.reduce((s,m)=>s+m.bytes,0),applied:null,stewardCost:null},storageSnapshot:D.storage,metricDefinitions:D.metrics};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='wolf-demo-summary-'+state.days+'d.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);const toast=document.getElementById('toast');toast.textContent='Демо-сводка и определения метрик экспортированы';toast.hidden=false;setTimeout(()=>toast.hidden=true,3500);});
  window.addEventListener('hashchange',route);route();
})();
